/**
 * The hyper-jev skill starter carries a copy of src/core so it runs without this package.
 * The copy is generated by scripts/sync-skill-core.mjs; this test fails when it drifts.
 * Skipped when the package is used outside this repository.
 */
import test from "node:test";
import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { readdir, readFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const pkg = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(pkg, "src/core");
const starter = resolve(pkg, "../../.claude/skills/hyper-jev/templates/starter/src/core");

test("the skill starter's core matches the package core", { skip: !existsSync(starter) && "no hyper-jev skill next to this package" }, async () => {
  const ours = (await readdir(source)).filter((f) => f.endsWith(".ts")).sort();
  const theirs = (await readdir(starter)).filter((f) => f.endsWith(".ts")).sort();
  assert.deepEqual(theirs, ours, "the starter's core has different files; run node scripts/sync-skill-core.mjs");
  for (const file of ours) {
    const same = (await readFile(join(source, file), "utf8")) === (await readFile(join(starter, file), "utf8"));
    assert.ok(same, `${file} differs from the package; run node scripts/sync-skill-core.mjs`);
  }
});
